_GRAMS_RE = re.compile(r"(\d+(?:[.,]\d+)?)\s*(?:g|gr|gram)\b", re.IGNORECASE)


def _extract_grams(text):
    """Sorgudan gram miktarını yakala (ör. '300g tavuk' → 300.0). Yoksa None."""
    m = _GRAMS_RE.search(text or "")
    if m:
        try:
            val = float(m.group(1).replace(",", "."))
            if 0 < val <= 5000:
                return val
        except ValueError:
            pass
    return None


def _coach_search_food(query):
    """Birleşik besin araması — alaka-kapısı + TR→EN normalizasyonlu.

    1) Ham sorguyla FatSecret dene (İngilizce sorgular ve marka adları doğrudan
       eşleşir). Sonuçları ALAKA filtresinden geçir: FatSecret eşleyemediği
       Türkçe sorgulara ilgisiz jenerik besin döndürdüğü için ('patates
       kızartması' → 'Soy Nuts') ad-token örtüşmesi olmayanları ele.
    2) Alakalı sonuç yoksa sorguyu İngilizce'ye çevirip tekrar dene — FatSecret
       verisi ağırlıklı İngilizce, Türkçe serbest metin nadiren eşleşir.
    3) Son çare: statik Türkçe tablo, sonra LLM tahmini.
    Hepsi 100g bazlı 'per_100g' makroları içerir."""
    raw = (query or "").strip()

    relevant = [r for r in (_food_search_fatsecret(raw) or [])
                if _is_relevant_food(raw, r.get("name", ""))]
    if relevant:
        return relevant

    english = _normalize_food_query_en(raw)
    if english and english.lower() != raw.lower():
        relevant = [r for r in (_food_search_fatsecret(english) or [])
                    if _is_relevant_food(english, r.get("name", ""))]
        if relevant:
            return relevant

    return _food_search_static(raw) or _food_search_llm(english or raw) or []


def _today_nutrition_totals(user_id):
    """Bugünün beslenme toplamları (MealLog — tek kanonik beslenme defteri).
    menu.py'deki 'consumed' ile AYNI tarih anahtarını (utcnow %d.%m) kullanır ki
    koçun 'kalan bütçe'si ile menü analizinin 'kalanı' birebir tutarlı olsun.
    (Faz C tarih semantiğini tüm okuyucularda birlikte ISO/Istanbul'a taşıyacak.)"""
    today_key = day_key()
    row = db.session.query(
        db.func.coalesce(db.func.sum(MealLog.kalori), 0),
        db.func.coalesce(db.func.sum(MealLog.protein), 0),
        db.func.coalesce(db.func.sum(MealLog.karb), 0),
        db.func.coalesce(db.func.sum(MealLog.yag), 0),
        db.func.count(MealLog.id),
    ).filter(
        MealLog.user_id == user_id,
        MealLog.tarih == today_key,
    ).first()
    return {
        "calories": round(row[0]),
        "protein": round(row[1], 1),
        "carbs": round(row[2], 1),
        "fat": round(row[3], 1),
        "entry_count": row[4],
    }


def _remaining_macros_for_user(user_id):
    """Kullanicinin bugun KALAN gunluk makro butcesi.

    Bu fonksiyon ARTIK hedef-makro formulunun sahibi DEGIL (Sprint 13 PR2, C2):
    dagilimi tek kanonik otorite (`app.services.nutrition_targets`) turetir,
    burada kalan yalnizca kocun sahip oldugu isler — en son UserSession'i ve
    bugunun kanonik MealLog toplamlarini okumak. Ayni otoriteyi menu analizi,
    barkod ve fitx_mcp de tuketir; formul artik ucuncu kez yazilmaz (F2).
    Deterministik; LLM yok. Yapilandirilmis hedef yoksa None doner — sayi
    uydurulmaz (F3a).
    """
    sess = (UserSession.query.filter_by(user_id=user_id)
            .order_by(UserSession.created_at.desc()).first())
    targets = derive_daily_macro_targets(
        getattr(sess, "target_calories", None), getattr(sess, "goal", None))
    if targets is None:
        return None
    remaining = remaining_macro_budget(targets, _today_nutrition_totals(user_id))
    return remaining.as_dict()


def _today_workout_totals(user_id):
    """Bugünün antrenman toplam volümü (Istanbul günü). WorkoutLog erişimi ve
    tamamlama-işaretçisini (D4) hariç tutma, paylaşılan training-history temelinden
    gelir (Sprint 6 PR1): koç bağlamındaki "bugünkü hacim/egzersiz sayısı"nı
    işaretçi rowları şişirmez; "antrenman yapıldı mı" sinyali ayrı yollardan
    (nudge/PumpCheck) hâlâ işaretçiyi görür."""
    today = app_today()
    entries = fetch_workout_entries(user_id, today, today)
    return {"total_volume": round(total_volume(entries), 1), "entry_count": len(entries)}


# ── S1: tur-içi stage→confirm kilidi ────────────────────────────────────────
# Onay ("evet") sistem isteminde modele bırakılmıştı — olasılıksal bir korkuluk.
# Arkadaş içeriğine gömülü bir enjeksiyon, aynı araç döngüsü içinde stage +
# confirm çağırtıp kullanıcı öneriyi hiç görmeden sahte kayıt commit'letebilirdi.
# Deterministik kural: bu turda stage edilen PendingAction bu turda commit
# EDİLEMEZ — commit ancak kullanıcının staged öneriyi görüp yeni bir mesaj
# gönderdiği sonraki turda mümkündür. İşaret g'de yaşar (istek-kapsamlı; koç
# araç döngüsü tek HTTP isteğinde koşar).

def _begin_coach_turn(user_message="", history=None):
    g._coach_staged_ids = set()
    # PR3: the plan-mutation budget is per turn, and "a turn" is defined here so
    # the blocking and streaming paths cannot drift into two different answers.
    # PR4: confirmation intent is derived from the raw current user turn.
    coach_plan_tools.begin_turn(user_message, history=history)


def _mark_staged_this_turn(pending_id):
    ids = getattr(g, "_coach_staged_ids", None)
    if ids is None:
        ids = set()
        g._coach_staged_ids = ids
    ids.add(pending_id)


def _staged_this_turn(pending_id):
    return pending_id in getattr(g, "_coach_staged_ids", set())


_SAME_TURN_CONFIRM_MSG = (
    "Bu kayıt bu tur içinde stage edildi; kullanıcı öneriyi henüz görmedi. "
    "Staged kaydı kullanıcıya özetle ve açık onay iste — onay bir SONRAKİ "
    "kullanıcı mesajıyla gelirse confirm aracını tekrar çağır.")


def _staging_refusal(user_id):
    if not coach_confirmation.should_refuse_new_staging(user_id):
        return None
    return json.dumps(
        coach_confirmation.staging_refusal_payload(), ensure_ascii=False)


def _tool_fetch_nutrition_and_stage_log(user_id, food_query):
    """TOOL (staging): FatSecret'tan makro çek → PendingAction'a yaz → LLM'e döndür.
    KALICI KAYIT YAPMAZ. Durum geçişi: (yok) → staged."""
    refusal = _staging_refusal(user_id)
    if refusal is not None:
        return refusal
    food_query = (food_query or "").strip()
    if not food_query:
        return json.dumps({"status": "error", "message": "Yiyecek sorgusu boş."}, ensure_ascii=False)

    results = _coach_search_food(food_query)
    if not results:
        # FatSecret/fallback boş → LLM kullanıcıdan netleştirme istesin (hata yönetimi).
        return json.dumps({
            "status": "not_found",
            "message": f"'{food_query}' için besin verisi bulunamadı. Kullanıcıdan daha açık bir tanım iste (pişirme şekli, marka, miktar).",
        }, ensure_ascii=False)

    top = results[0]
    per_100g = top.get("per_100g") or top.get("macros") or {}
    grams = _extract_grams(food_query) or 100.0
    scale = grams / 100.0
    payload = {
        # B5: get(..., 0) açık None değerinde 0 vermez → float(None) TypeError.
        # `or 0` ile None/boş değerleri de 0'a indir.
        "food_name": (top.get("name") or food_query)[:200],
        "calories": round(float(per_100g.get("calories") or 0) * scale, 1),
        "protein": round(float(per_100g.get("protein") or 0) * scale, 1),
        "carbs": round(float(per_100g.get("carbs") or 0) * scale, 1),
        "fat": round(float(per_100g.get("fat") or 0) * scale, 1),
        "serving_size": f"{grams:g} g",
    }

    # Deterministik uyum degerlendirmesi (compatibility_score 0-100). Tum matematik
    # nutrition_pipeline'da yapilir; LLM yalnizca bu sabit sayilari sunar.
    remaining = _remaining_macros_for_user(user_id)
    evaluation = None
    if remaining is not None:
        evaluation = nutrition_pipeline.build_evaluation(
            food_id=top.get("food_id", ""),
            name=payload["food_name"],
            standardized_serving=payload["serving_size"],
            macros={
                "calories": payload["calories"],
                "protein": payload["protein"],
                "carbs": payload["carbs"],
                "fat": payload["fat"],
            },
            remaining=remaining,
        )

    # Tek aktif 'staged' meal: önceki bekleyenleri temizle, yenisini yaz, commit et.
    _cleanup_stale_pending(user_id)
    PendingAction.query.filter_by(user_id=user_id, action_type="log_meal").delete()
    staged_row = PendingAction(user_id=user_id, action_type="log_meal", payload=payload)
    db.session.add(staged_row)
    db.session.commit()
    _mark_staged_this_turn(staged_row.id)

    return json.dumps({
        "status": "staged",
        "staged_food": payload,
        "evaluation": evaluation,
        "instruction": ("Makroları ve (varsa) compatibility_score'u kullanıcıya AYNEN, "
                        "değiştirmeden ve yeniden hesaplamadan sun — sayılar kesindir. "
                        "Sonra 'Günlüğüne kaydedeyim mi?' diye onay iste; onay gelmeden "
                        "confirm_and_commit_meal_log çağırma."),
    }, ensure_ascii=False)


def _tool_confirm_and_commit_meal_log(user_id):
    """TOOL (commit): En son staged meal'i kalıcı MealLog kaydına taşı (tek kanonik
    beslenme defteri — diyari/menü ile aynı tablo), PendingAction satırını sil.
    Durum geçişi: staged → committed."""
    pending = (PendingAction.query
               .filter_by(user_id=user_id, action_type="log_meal")
               .order_by(PendingAction.created_at.desc())
               .first())
    if not pending:
        # 'evet' dendi ama ortada bekleyen yemek yok → güvenli hata yönetimi.
        return json.dumps({
            "status": "no_pending",
            "message": "Onaylanacak bekleyen bir yemek kaydı yok. Önce kullanıcının ne yediğini öğrenip fetch_nutrition_and_stage_log çağır.",
        }, ensure_ascii=False)

    if _staged_this_turn(pending.id):
        return json.dumps({
            "status": "needs_user_confirmation",
            "message": _SAME_TURN_CONFIRM_MSG,
        }, ensure_ascii=False)

    data = pending.payload or {}
    cal = float(data.get("calories", 0) or 0)
    pro = float(data.get("protein", 0) or 0)
    carb = float(data.get("carbs", 0) or 0)
    fat = float(data.get("fat", 0) or 0)
    name = (data.get("food_name") or "Yemek")[:200]

    # Staged makrolar (FatSecret/LLM kaynaklı) porsiyon-sanity kapısından geçmeden
    # kanonik deftere yazılıyordu — diyari/menü/UI hepsi kısarken koç yolu atlıyordu.
    # Fiziksel olarak imkânsız bir porsiyonu (örn. 9999 kcal) makul tavanlara kıs.
    clamped = nutrition_pipeline.clamp_serving_macros(cal, pro, carb, fat)
    if clamped != (cal, pro, carb, fat):
        current_app.logger.warning(
            "[COACH] Staged makrolar makul değil (%s) — kısılıyor %s → %s",
            name, (cal, pro, carb, fat), clamped)
        cal, pro, carb, fat = clamped

    # Satırı önce atomik 'sahiplen': eşzamanlı çift-onayda (double-confirm) yalnızca
    # biri 1 satır siler; diğeri 0 alır ve çift loglamadan döner (3.10 idempotent).
    claimed = PendingAction.query.filter_by(id=pending.id).delete(synchronize_session=False)
    if not claimed:
        db.session.rollback()
        return json.dumps({
            "status": "no_pending",
            "message": "Bu kayıt zaten işlendi.",
        }, ensure_ascii=False)

    db.session.add(MealLog(
        user_id=user_id, ogun="AI Koç", yemekler=name,
        kalori=cal, protein=pro, karb=carb, yag=fat,
        tarih=day_key(), source="coach",
    ))
    award_xp(user_id, 10)
    log_activity(user_id, "nutrition_logged", f"{name} — {round(cal)} kcal")
    db.session.commit()

    return json.dumps({
        "status": "committed",
        "logged": {
            "food_name": name, "calories": cal, "protein": pro,
            "carbs": carb, "fat": fat, "serving_size": data.get("serving_size", ""),
        },
        "xp_awarded": 10,
        "today_totals": _today_nutrition_totals(user_id),
    }, ensure_ascii=False)


_PENDING_TTL = timedelta(hours=1)


def _cleanup_stale_pending(user_id, max_age=_PENDING_TTL):
    """Onaylanmadan bayatlamış (>1 saat) bekleyen aksiyonları toplu sil (3.10).

    Onay hiç gelmeyen 'staged' kayıtlar birikip sonraki bir 'evet'te yanlış/eski
    bir yemeği loglayabilir; periyodik toplu temizlik bu riski kapatır. Commit
    çağırana bırakılmaz — kendi içinde idempotenttir, hata boğulur."""
    try:
        cutoff = datetime.utcnow() - max_age
        deleted = (PendingAction.query
                   .filter(PendingAction.user_id == user_id,
                           PendingAction.created_at < cutoff)
                   .delete(synchronize_session=False))
        if deleted:
            current_app.logger.info(
                "[PENDING] %d bayat bekleyen aksiyon temizlendi (user=%s)", deleted, user_id)
    except Exception:
        db.session.rollback()


def _tool_stage_workout_log(user_id, exercise_name, sets, reps, weight_kg):
    """TOOL (staging): Antrenmanı onaya hazırla. Kalıcı kayıt yapmaz."""
    exercise_name = (exercise_name or "").strip()
    if not exercise_name:
        return json.dumps({"status": "error", "message": "Egzersiz adı boş."}, ensure_ascii=False)
    try:
        sets = int(sets or 0)
        reps = int(reps or 0)
        weight = float(weight_kg or 0)
    except (TypeError, ValueError):
        sets, reps, weight = 3, 10, 0.0
    if sets <= 0:
        sets = 3
    if reps <= 0:
        reps = 10
    if weight < 0:
        weight = 0.0

    refusal = _staging_refusal(user_id)
    if refusal is not None:
        return refusal

    payload = {
        "exercise_name": exercise_name[:120],
        "sets": sets, "reps": reps, "weight_kg": weight,
        "volume": round(sets * reps * weight, 1),
    }
    _cleanup_stale_pending(user_id)
    PendingAction.query.filter_by(user_id=user_id, action_type="log_workout").delete()
    staged_row = PendingAction(user_id=user_id, action_type="log_workout", payload=payload)
    db.session.add(staged_row)
    db.session.commit()
    _mark_staged_this_turn(staged_row.id)

    return json.dumps({
        "status": "staged",
        "staged_workout": payload,
        "instruction": "Antrenmanı özetle ve onay iste; onay gelince confirm_and_commit_workout_log çağır.",
    }, ensure_ascii=False)


def _tool_confirm_and_commit_workout_log(user_id):
    """TOOL (commit): En son staged antrenmanı kalıcı WorkoutLog'a taşı."""
    pending = (PendingAction.query
               .filter_by(user_id=user_id, action_type="log_workout")
               .order_by(PendingAction.created_at.desc())
               .first())
    if not pending:
        return json.dumps({
            "status": "no_pending",
            "message": "Onaylanacak bekleyen bir antrenman kaydı yok.",
        }, ensure_ascii=False)

    if _staged_this_turn(pending.id):
        return json.dumps({
            "status": "needs_user_confirmation",
            "message": _SAME_TURN_CONFIRM_MSG,
        }, ensure_ascii=False)

    d = pending.payload or {}
    # Satırı önce atomik 'sahiplen' (double-confirm idempotency — 3.10).
    claimed = PendingAction.query.filter_by(id=pending.id).delete(synchronize_session=False)
    if not claimed:
        db.session.rollback()
        return json.dumps({
            "status": "no_pending",
            "message": "Bu kayıt zaten işlendi.",
        }, ensure_ascii=False)

    db.session.add(WorkoutLog(
        user_id=user_id,
        exercise_name=(d.get("exercise_name") or "Egzersiz")[:120],
        sets=int(d.get("sets", 3)), reps=int(d.get("reps", 10)),
        weight_kg=float(d.get("weight_kg", 0)), volume=float(d.get("volume", 0)),
    ))
    award_xp(user_id, 15)
    # BİLİNÇLİ: 'workout_logged' quest/challenge hunisi (_claim_quest/record_event)
    # burada KASITLI çağrılmaz (triage 2026-07-17 #6). Diğer iki WorkoutLog yazıcısı
    # (/workout/complete, pump-check tool'u) SEANS başına bir kez ateşlerken bu tool
    # tek EGZERSİZ kaydeder; her egzersizde ateşlemek seans-tabanlı weekly_workouts
    # challenge'ını ve workout_logged günlük quest'ini şişirirdi. XP (xp_earned) yine
    # akar. Seans-başı dedup ile huniyi bağlamak istenirse ürün kararı gerekir.
    log_activity(user_id, "workout_completed",
                 f"{d.get('exercise_name')} — {d.get('sets')}x{d.get('reps')} @ {d.get('weight_kg')}kg")
    db.session.commit()

    return json.dumps({
        "status": "committed",
        "logged": d,
        "xp_awarded": 15,
        "today_totals": _today_workout_totals(user_id),
    }, ensure_ascii=False)


def _tool_cancel_pending_log(user_id):
    """TOOL: Kullanıcı reddederse SON stage edilen kaydı sil (meal VEYA workout).

    Tüm bekleyenleri silmek yerine en yenisini hedefler — tek bir 'iptal' hem
    staged meal'i hem staged workout'u birden silmesin (#11). Kullanıcı genelde
    en son sunulan kaydı reddeder; o da en yeni olandır."""
    pending = (PendingAction.query
               .filter_by(user_id=user_id)
               .order_by(PendingAction.created_at.desc(), PendingAction.id.desc())
               .first())
    if not pending:
        return json.dumps({"status": "cancelled", "removed": 0}, ensure_ascii=False)
    cancelled_type = pending.action_type
    removed = PendingAction.query.filter_by(id=pending.id).delete()
    db.session.commit()
    return json.dumps({"status": "cancelled", "removed": removed,
                       "cancelled_type": cancelled_type}, ensure_ascii=False)


