# LLM'in yazabileceği anahtarlar beyaz-listede (rastgele anahtar şişmesini önle).
_MEMORY_KEYS = ("injuries", "fitness_goals", "equipment_available",
                "dietary_restrictions", "preferences")
_MEMORY_VALUE_MAXLEN = 2000  # serileştirilmiş değer üst sınırı (LLM girdisi)


def _tool_manage_user_memory(user_id, action, key=None, value=None):
    """TOOL: Kullanıcının uzun süreli metadata'sını (sakatlıklar, tercihler) oku/yaz.
    User.user_metadata (JSON) ile eşlenir. user_id ASLA LLM'den gelmez."""
    action = (action or "").strip().lower()
    key = (key or "").strip()
    user = db.session.get(User, user_id)
    if not user:
        return json.dumps({"status": "error", "message": "Kullanıcı bulunamadı."}, ensure_ascii=False)
    meta = dict(user.user_metadata or {})

    if action == "get":
        if key:
            return json.dumps({"status": "ok", "action": "get", "key": key,
                               "value": meta.get(key)}, ensure_ascii=False)
        return json.dumps({"status": "ok", "action": "get", "memory": meta}, ensure_ascii=False)

    if action == "update":
        if key not in _MEMORY_KEYS:
            return json.dumps({"status": "error",
                               "message": f"Geçersiz anahtar: '{key}'. Geçerli anahtarlar: {', '.join(_MEMORY_KEYS)}"},
                              ensure_ascii=False)
        # 'update' DAİMA bir değer ister. None/boş ile çağrı kayıtlı veriyi (ör.
        # sakatlık) sessizce silmesin — sakatlık akışında "yok" için 'Hiçbiri' yazılır.
        if value is None or (isinstance(value, str) and not value.strip()):
            return json.dumps({"status": "error",
                               "message": "'update' için boş olmayan bir value gerekli (silmek için açık bir değer gönder, ör. 'Hiçbiri')."},
                              ensure_ascii=False)
        try:
            if len(json.dumps(value, ensure_ascii=False)) > _MEMORY_VALUE_MAXLEN:
                return json.dumps({"status": "error", "message": "Değer çok uzun."}, ensure_ascii=False)
        except (TypeError, ValueError):
            return json.dumps({"status": "error", "message": "Değer JSON'a çevrilemedi."}, ensure_ascii=False)
        # JSON kolon: yerinde mutasyon SQLAlchemy tarafından izlenmez — yeni dict ata
        # + flag_modified ile değişikliği garanti et (aksi halde commit kalıcı olmaz).
        meta[key] = value
        user.user_metadata = meta
        flag_modified(user, "user_metadata")
        try:
            db.session.commit()
        except Exception as e:
            db.session.rollback()
            current_app.logger.warning("[MEMORY] commit başarısız: %s: %s", type(e).__name__, e)
            return json.dumps({"status": "error", "message": "Kaydedilemedi, tekrar dene."}, ensure_ascii=False)
        return json.dumps({"status": "ok", "action": "update", "key": key,
                           "value": value}, ensure_ascii=False)

    return json.dumps({"status": "error",
                       "message": f"Geçersiz action: '{action}'. 'get' veya 'update' olmalı."},
                      ensure_ascii=False)


# ── query_fitx_metrics ────────────────────────────────────────────────────────
_VALID_DATE_RANGES = ("today", "last_7_days", "current_month")
_VALID_METRICS = ("calories", "water_ml", "sleep_hours", "weight_kg", "volume_lifted")


def _range_start_day(date_range):
    """date_range → aralığın BAŞLANGIÇ Istanbul günü (date). Bitiş daima bugün."""
    today = app_today()
    return {
        "today": today,
        "last_7_days": today - timedelta(days=6),
        "current_month": today.replace(day=1),
    }.get(date_range)


def _range_keys(date_range):
    """ISO-string tarih kolonları (MealLog.tarih, WaterLog.date_key) için (lo, hi)
    ISO anahtar çifti. 'YYYY-MM-DD' sözlüksel olarak sıralandığı için string
    karşılaştırması doğru aralığı verir: col >= lo AND col <= hi."""
    start = _range_start_day(date_range)
    return (start.isoformat(), app_today().isoformat()) if start else None


def _range_bounds(date_range):
    """datetime kolonları (created_at, naive UTC) için yarı-açık [start, end) UTC
    sınırları: col >= start AND col < end. utc_day_bounds Istanbul gününü baz alır."""
    start_day = _range_start_day(date_range)
    if not start_day:
        return None
    start, _ = utc_day_bounds(start_day)
    _, end = utc_day_bounds(app_today())
    return start, end


def _tool_query_fitx_metrics(user_id, metric_type, date_range):
    """TOOL: Kullanıcının geçmiş metriklerini parametrik (HAM SQL YOK) sorgula.
    Enum'lar beyaz-listede; her metrik sabit, güvenli bir sorguya eşlenir."""
    metric_type = (metric_type or "").strip()
    date_range = (date_range or "").strip()
    if metric_type not in _VALID_METRICS:
        return json.dumps({"status": "error",
                           "message": f"Geçersiz metric_type: '{metric_type}'. Geçerli: {', '.join(_VALID_METRICS)}"},
                          ensure_ascii=False)
    if date_range not in _VALID_DATE_RANGES:
        return json.dumps({"status": "error",
                           "message": f"Geçersiz date_range: '{date_range}'. Geçerli: {', '.join(_VALID_DATE_RANGES)}"},
                          ensure_ascii=False)

    if metric_type == "sleep_hours":
        # Uyku SÜRESİ (saat) verisi YOK; yalnızca subjektif kalite (1-5) var ve o da
        # [HAFTALIK CHECK-IN TRENDİ] bağlam bloğunda zaten sağlanıyor. Veri uydurma.
        return json.dumps({"status": "unsupported", "metric_type": "sleep_hours",
                           "message": "Uyku süresi (saat) takibi yok. Subjektif uyku "
                                      "kalitesi (1-5) için [HAFTALIK CHECK-IN TRENDİ] "
                                      "bağlam bloğuna bak."}, ensure_ascii=False)

    base = {"status": "ok", "metric_type": metric_type, "date_range": date_range}

    if metric_type == "calories":
        lo, hi = _range_keys(date_range)
        total = db.session.query(db.func.coalesce(db.func.sum(MealLog.kalori), 0)).filter(
            MealLog.user_id == user_id, MealLog.tarih >= lo, MealLog.tarih <= hi).scalar()
        return json.dumps({**base, "value": round(total or 0), "unit": "kcal"}, ensure_ascii=False)

    if metric_type == "water_ml":
        lo, hi = _range_keys(date_range)
        cups = db.session.query(db.func.coalesce(db.func.sum(WaterLog.count), 0)).filter(
            WaterLog.user_id == user_id, WaterLog.date_key >= lo, WaterLog.date_key <= hi).scalar()
        return json.dumps({**base, "value": round((cups or 0) * 240), "unit": "ml",
                           "detail": f"{cups or 0} bardak × 240 ml"}, ensure_ascii=False)

    if metric_type == "volume_lifted":
        start, end = _range_bounds(date_range)
        total = db.session.query(db.func.coalesce(db.func.sum(WorkoutLog.volume), 0)).filter(
            WorkoutLog.user_id == user_id,
            WorkoutLog.created_at >= start, WorkoutLog.created_at < end).scalar()
        return json.dumps({**base, "value": round(total or 0, 1), "unit": "kg"}, ensure_ascii=False)

    if metric_type == "weight_kg":
        start, end = _range_bounds(date_range)
        rows = (WeeklyLog.query.filter(
            WeeklyLog.user_id == user_id,
            WeeklyLog.created_at >= start, WeeklyLog.created_at < end)
            .order_by(WeeklyLog.created_at.asc()).all())
        if not rows:
            return json.dumps({**base, "value": None, "unit": "kg",
                               "message": "Bu aralıkta kilo kaydı yok."}, ensure_ascii=False)
        first, last = rows[0].weight, rows[-1].weight
        # L1: WeeklyLog.weight NULL olabilir; round(None, 1) TypeError atardı
        # (blanket except'e düşüp generic hataya dönerdi). None'ı açıkça karşıla.
        if last is None:
            return json.dumps({**base, "value": None, "unit": "kg",
                               "message": "Bu aralıkta geçerli kilo kaydı yok."}, ensure_ascii=False)
        change = round(last - first, 1) if first is not None else None
        return json.dumps({**base, "value": round(last, 1), "unit": "kg",
                           "change": change, "entries": len(rows)}, ensure_ascii=False)

    return json.dumps({"status": "error", "message": f"Bilinmeyen metric_type: {metric_type}"},
                      ensure_ascii=False)


# ── analyze_gym_photo (multimodal Pump Check) ─────────────────────────────────
def _parse_photo_validation(raw):
    """Modelin ham yanıtından {"is_gym":bool,"form_rating":1-10,"reason":str} ayıkla."""
    s = (raw or "").strip().replace("```json", "").replace("```", "")
    start = s.find("{")
    end = s.rfind("}") + 1
    if start != -1 and end > start:
        s = s[start:end]
    try:
        data = json.loads(s)
    except (json.JSONDecodeError, TypeError, ValueError):
        data = {}
    try:
        rating = int(data.get("form_rating") or 0)
    except (TypeError, ValueError):
        rating = 0
    rating = max(1, min(rating, 10)) if rating else 0  # 1..10'a kıs (0 = bilinmiyor)
    return {"is_gym": bool(data.get("is_gym", False)), "form_rating": rating,
            "reason": str(data.get("reason", ""))[:300]}


def _tool_analyze_gym_photo(user_id, s3_key):
    """TOOL: S3'teki bir antrenman fotoğrafını Bedrock (Sonnet) ile doğrula; geçerliyse
    günlük (idempotent) Pump Check ödülünü ver. user_id ASLA LLM'den gelmez; s3_key
    LLM'den gelir → sahiplik (IDOR) sınırı zorunlu."""
    s3_key = (s3_key or "").strip()
    if not s3_key:
        return json.dumps({"status": "error", "message": "s3_key boş."}, ensure_ascii=False)
    if not (BEDROCK_ENABLED and _anthropic is not None):
        return json.dumps({"status": "error", "message": "Görsel doğrulama (Bedrock) şu an etkin değil."},
                          ensure_ascii=False)
    if not s3_helper.is_enabled():
        return json.dumps({"status": "error", "message": "Görsel deposu (S3) yapılandırılmamış."},
                          ensure_ascii=False)

    # IDOR sınırı: anahtar bu kullanıcıya ait olmalı (yol içinde '/<user_id>/').
    try:
        image_bytes = s3_helper.get_object_bytes(s3_key, expected_user_id=user_id)
    except Exception as e:
        current_app.logger.info("[ANALYZE PHOTO] görsel alınamadı: %s: %s", type(e).__name__, e)
        return json.dumps({"status": "error", "message": "Görsel alınamadı veya sana ait değil."},
                          ensure_ascii=False)

    # Sprint 7 PR2 (correction #2): idempotency preflight, Bedrock görü çağrısından
    # ÖNCE. Bugün zaten tamamlandıysa pahalı görsel analiz ATLANIR (replay'de gereksiz
    # sağlayıcı işi yok). Yarış-güvenli asıl iddia uq_pump_check_day.
    from app.services.workout_completion import already_completed_today
    if already_completed_today(user_id, app_today()):
        return json.dumps({"status": "already_done", "awarded": False,
                           "message": "Bugünkü antrenmanını zaten tamamladın."},
                          ensure_ascii=False)

    media_type = s3_helper.media_type_for_key(s3_key)
    try:
        if image_bytes and len(image_bytes) > 1_500_000:
            from app.services.menu_ocr import _compress_image_for_vision
            image_bytes, media_type = _compress_image_for_vision(image_bytes)
    except Exception:
        pass  # sıkıştırma başarısızsa ham baytlarla devam

    prompt = (
        "Sen bir fitness uygulamasının 'Pump Check' görsel doğrulayıcısısın. Görseli "
        "incele: bir spor salonu/antrenman ortamı mı? Kişinin fiziksel formunu/çabasını "
        "1-10 arası puanla. SADECE şu katı JSON'u döndür, başka hiçbir şey yazma: "
        '{"is_gym": true|false, "form_rating": 1-10, "reason": "kısa Türkçe gerekçe"}'
    )
    try:
        raw = _bedrock_validate_image(image_bytes, media_type, prompt, max_tokens=200)
    except Exception as e:
        current_app.logger.warning("[ANALYZE PHOTO] Bedrock başarısız: %s: %s", type(e).__name__, e)
        return json.dumps({"status": "error", "message": "Görsel analizi şu an yapılamadı."},
                          ensure_ascii=False)
    if not (raw or "").strip():
        # Boş model yanıtı (transport/model aksaklığı): _parse_photo_validation bunu
        # is_gym:false'a çevirip "burası spor salonu değil" gibi YANLIŞ bir cevaba
        # dönüştürürdü. Gerçek "değil" kararından ayır, hata olarak dön.
        current_app.logger.warning("[ANALYZE PHOTO] Bedrock boş yanıt döndürdü")
        return json.dumps({"status": "error", "message": "Görsel analizi şu an yapılamadı."},
                          ensure_ascii=False)
    result = _parse_photo_validation(raw)

    if not result["is_gym"]:
        return json.dumps({"status": "ok", "is_gym": False, "form_rating": result["form_rating"],
                           "reason": result["reason"], "awarded": False}, ensure_ascii=False)

    # Kanonik tamamlanma mutasyonu (Sprint 7 PR2): UI /workout/complete ile AYNI
    # sınır (app/services/workout_completion) — PumpCheck + marker + XP + görev +
    # challenge TEK atomik transaction. Bu araç yalnızca görsel analiz + yanıttan
    # sorumlu; rakip tamamlanma semantiği TUTMAZ. Kanıt-yalnızca kayıtçılar
    # (commit_workout_log, fitx_mcp) bu yolu ASLA çağırmaz.
    from app.services.workout_completion import CompleteWorkoutCommand, complete_workout
    try:
        outcome = complete_workout(CompleteWorkoutCommand(
            user_id=user_id,
            today=app_today(),
            image_key=s3_key,
            location_type="ai_tool",
            description=result["reason"][:200],
            workout_score=latest_training_plan_score(user_id),
            visibility="private",
            shared_friend_ids=(),
            valid=True,
            fallback=False,
            base_xp=10,
            photo_bonus=25,
            activity_text="Pump Check doğrulandı (AI koç)",
            entry_path="ai_tool",
        ))
    except Exception as e:
        current_app.logger.warning("[ANALYZE PHOTO] tamamlanma başarısız: %s: %s", type(e).__name__, e)
        return json.dumps({"status": "error", "message": "Ödül kaydedilemedi, tekrar dene."},
                          ensure_ascii=False)

    if outcome.already_completed:
        # Bedrock görüsünden SONRA yarış kaybeden (form_rating/reason zaten hesaplandı).
        return json.dumps({"status": "already_done", "is_gym": True,
                           "form_rating": result["form_rating"], "reason": result["reason"],
                           "awarded": False, "message": "Bugünkü antrenmanını zaten tamamladın."},
                          ensure_ascii=False)

    return json.dumps({"status": "committed", "is_gym": True,
                       "form_rating": result["form_rating"], "reason": result["reason"],
                       "awarded": True, "xp_awarded": outcome.xp_awarded},
                      ensure_ascii=False)


