def _to_openai_tool(t):
    """Kanonik tanım → OpenAI function-calling biçimi."""
    return {"type": "function", "function": {
        "name": t["name"], "description": t["description"], "parameters": t["parameters"]}}


def _to_anthropic_tool(t):
    """Kanonik tanım → Anthropic Messages API biçimi (input_schema = parameters)."""
    return {"name": t["name"], "description": t["description"], "input_schema": t["parameters"]}


# OpenAI döngüsü bu listeyi olduğu gibi kullanır (davranış değişmez).
COACH_TOOLS = [_to_openai_tool(t) for t in _COACH_TOOL_DEFS]
# Bedrock/Anthropic döngüsü için aynı kaynaktan türetilen biçim.
COACH_TOOLS_ANTHROPIC = [_to_anthropic_tool(t) for t in _COACH_TOOL_DEFS]


def _coach_tool_defs_for_call(user_id=None):
    """Bu istekte modele sunulacak kanonik araç tanımları.

    Plan düzenleme araçları bayrak AÇIKken TEK kanonik tanımdan (coach_plan_tools
    .PLAN_MUTATION_TOOL_DEFS / confirmation defs) eklenir — iki sağlayıcı biçimi
    de aşağıda BU listeden türetilir, yani bir sağlayıcının şeması diğerinden
    ayrışamaz (brief §41). Bayrak KAPALIYKEN liste, PR3 öncesiyle AYNI nesnedir:
    ek kopya, ek alan, ek boşluk yok.
    """
    defs = coach_confirmation.filter_coach_tool_defs(_COACH_TOOL_DEFS, user_id)
    if not coach_plan_tools.plan_mutation_tools_enabled():
        return defs
    return defs + list(
        coach_plan_tools.published_plan_tool_defs(user_id))


def _openai_tools_for_call(user_id=None):
    """COACH_TOOLS'un çağrı-zamanı karşılığı (bayrak KAPALIYKEN aynı içerik).

    Bayrak bir istek özelliğidir (`current_app.config`), modül import'u değil —
    liste bu yüzden çağrı anında kurulur. Modül-global COACH_TOOLS DEĞİŞMEDEN
    kalır: mevcut testler ve import yolları onu sekiz aracın kanonik OpenAI
    projeksiyonu olarak kullanmayı sürdürür.
    """
    return [_to_openai_tool(t) for t in _coach_tool_defs_for_call(user_id)]


def _dispatch_coach_tool(user_id, name, arguments_json):
    """LLM'in istediği aracı sunucu tarafında çalıştır. user_id ASLA LLM'den
    gelmez — güvenlik için current_user'dan enjekte edilir. JSON string döndürür."""
    _assert_principal(user_id)
    arguments_parsed = True
    try:
        args = json.loads(arguments_json) if arguments_json else {}
    except (json.JSONDecodeError, TypeError):
        args = {}
        arguments_parsed = False

    # Plan düzenleme araçları (PR3) — mutasyon yüzeyi, en başta ayrılır.
    # Ayrıştırılamayan argümanlar bu yüzeyde {} DEĞİLDİR: undo argüman almadığı
    # için bozuk JSON'u boş nesneye katlamak, model hiç göndermediği bir çağrıyı
    # başarıyla yürütmek olurdu (brief §37/§38). Mevcut sekiz araç eski
    # davranışını (bozuk JSON → boş args) aynen korur.
    if name in coach_plan_tools.PLAN_WRITE_TOOL_NAMES:
        if not arguments_parsed:
            return json.dumps(
                coach_plan_tools.invalid_arguments_result(
                    "araç argümanları okunamadı"),
                ensure_ascii=False)
        if (name in coach_plan_tools.PLAN_MUTATION_TOOL_NAMES
                and coach_confirmation.should_block_plan_mutation(user_id)):
            return json.dumps(
                coach_confirmation.blocked_plan_mutation_payload(),
                ensure_ascii=False)
        return json.dumps(
            coach_plan_tools.execute_plan_tool(user_id, name, args),
            ensure_ascii=False)

    # Araç gövdesindeki beklenmeyen hatayı (özellikle DB commit/delete) merkezi
    # olarak yakala: oturumu rollback ile temizle (kirli transaction sonraki
    # commit'i de patlatmasın) ve koç turunu çökertmek yerine modele hata durumu
    # döndür. _assert_principal KASTEN bunun DIŞINDA — güvenlik ihlali dostça bir
    # mesaja dönüşmemeli, propagate etmeli.
    try:
        if name == "fetch_nutrition_and_stage_log":
            return _tool_fetch_nutrition_and_stage_log(user_id, args.get("food_query", ""))
        if name == "confirm_and_commit_meal_log":
            return _tool_confirm_and_commit_meal_log(user_id)
        if name == "stage_workout_log":
            return _tool_stage_workout_log(
                user_id, args.get("exercise_name", ""),
                args.get("sets"), args.get("reps"), args.get("weight_kg"),
            )
        if name == "confirm_and_commit_workout_log":
            return _tool_confirm_and_commit_workout_log(user_id)
        if name == "cancel_pending_log":
            return _tool_cancel_pending_log(user_id)
        if name == "manage_user_memory":
            return _tool_manage_user_memory(
                user_id, args.get("action", ""), args.get("key"), args.get("value"))
        if name == "query_fitx_metrics":
            return _tool_query_fitx_metrics(
                user_id, args.get("metric_type", ""), args.get("date_range", ""))
        if name == "analyze_gym_photo":
            return _tool_analyze_gym_photo(user_id, args.get("s3_key", ""))
        return json.dumps({"status": "error", "message": f"Bilinmeyen araç: {name}"}, ensure_ascii=False)
    except Exception:
        db.session.rollback()
        current_app.logger.warning("[COACH] araç '%s' çalışırken hata", name, exc_info=True)
        return json.dumps({"status": "error",
                           "message": "Araç çalışırken bir hata oluştu, tekrar dener misin?"},
                          ensure_ascii=False)


# COACH_HISTORY_LIMIT / COACH_HISTORY_CHAR_CAP / _sanitize_client_history
# app/services/memory_manager.py'ye taşındı (WS3) — başlıktaki re-export'lara bak.


_COACH_TOOL_LOOP_CAP = 5  # araç çağrısı zincirine güvenli üst sınır (iki sağlayıcı)


def _coach_turn_deadline():
    return time.monotonic() + AI_COACH_TURN_TIMEOUT_SECONDS


def _remaining_coach_turn_seconds(deadline):
    return max(0.0, deadline - time.monotonic())


def _coach_tool_fallback(language, kind="tool"):
    """Turun yumuşak hata metni — bu turda plan DEĞİŞTİYSE farklı bir doğru.

    Jenerik metin ("İşlemi tamamlayamadım, tekrar dener misin?") bir plan aracı
    kalıcı yazma yaptıktan sonra YANLIŞTIR: B-kuralı gereği sağlayıcı
    değiştirilmez ve tur buraya iner, ama mutasyon COMMIT'Lİdir. Kullanıcıyı
    tekrar denemeye çağırmak daha da kötüsüdür — yeni istek yeni `request_id`,
    yani yeni işlem kimliği demektir ve aynı düzenleme İKİNCİ kez uygulanır
    (tur-içi replay bunu yalnızca TEK sunucu turu boyunca engeller).

    Yalnızca metin değişir: yeni metin de bir hata-yedeğidir, dolayısıyla kota
    iadesi ve geçmişe-yazmama (B16) davranışı aynen korunur."""
    texts = _COACH_FALLBACKS[_coach_lang(language)]
    if coach_plan_tools.plan_changed_this_turn():
        return texts["tool_plan_saved"]
    if coach_plan_tools.proposal_created_this_turn():
        return texts["tool_plan_confirmation_pending"]
    return texts[kind]


class _BedrockFallback(Exception):
    """Bedrock döngüsü İLK çağrıda (henüz hiçbir araç çalışmadan) hata verdiğinde
    fırlatılır → OpenAI'ya güvenle düşülebilir. Bir araç YAN ETKİ ürettikten sonra
    oluşan hatalar bunu fırlatmaz (yarıda sağlayıcı değiştirip aracı tekrar
    çalıştırmaktan kaçınmak için)."""


def _run_coach_conversation(user_id, question, context, client_history=None,
                            language="tr", prepared_history=None):
    """Koç sohbeti yönlendiricisi: ortak mesajları kurar, Bedrock açıksa Bedrock
    araç-kullanım döngüsünü dener (ilk çağrı hatasında OpenAI'ya şeffafça düşer),
    aksi halde mevcut OpenAI döngüsünü çalıştırır; sonra geçmişi kalıcılaştırır.

    Geçmiş üç kaynaktan gelebilir (öncelik sırasıyla):
    1) prepared_history — WS1 kalıcı hafızadan kurulmuş rolling window
       (memory_manager.build_context_window). Sanitize/kırpma UYGULANMAZ (bütçe
       orada yönetildi) ve session'a YAZILMAZ (kalıcılık DB'de, record_turn).
    2) client_history — widget'ın gönderdiği sohbet (fallback yolu).
    3) session cookie — en eski davranış.
    Asıl 'staged' veri DB'deki PendingAction'da yaşar.
    """
    if prepared_history is not None:
        history = list(prepared_history)
        use_client = True  # session'a yazma (kalıcılık DB'de)
    else:
        use_client = client_history is not None
        if use_client:
            history = _sanitize_client_history(client_history)
            # Widget mevcut soruyu da history'nin sonuna iter; soruyu aşağıda biz
            # ayrıca eklediğimiz için sondaki user turlarını atıp çift eklemeyi önle.
            while history and history[-1]["role"] == "user":
                history.pop()
        else:
            history = list(session.get("coach_history", []))
        history = history[-COACH_HISTORY_LIMIT:]

    _begin_coach_turn(question, history=history)
    resolved = coach_confirmation.resolve_pending_turn(user_id, language)
    if resolved is not None:
        if prepared_history is None and client_history is None:
            new_history = history + [
                {"role": "user", "content": question[:COACH_HISTORY_CHAR_CAP]},
                {"role": "assistant", "content": resolved[:COACH_HISTORY_CHAR_CAP]},
            ]
            session["coach_history"] = new_history[-COACH_HISTORY_LIMIT:]
        return resolved

    deadline = _coach_turn_deadline()
    final_text = None
    if BEDROCK_ENABLED and _anthropic is not None:
        try:
            final_text = _run_coach_conversation_bedrock(
                user_id, question, context, history, language,
                deadline=deadline)
        except _BedrockFallback as e:
            current_app.logger.warning(
                "[COACH] Bedrock ilk çağrı başarısız, OpenAI'ya düşülüyor: %s", e)
            final_text = None
    if final_text is None:
        if _remaining_coach_turn_seconds(deadline) <= 0:
            current_app.logger.warning(
                "[COACH] turn budget exhausted before OpenAI fallback")
            final_text = _coach_tool_fallback(language)
        else:
            final_text = _run_coach_conversation_openai(
                user_id, question, context, history, language,
                deadline=deadline)

    # C3/B16 kararı response_formatter.finalize_reply'de: yedek/boş yanıt
    # dostça hata metnine çevrilir ve geçmişe yazılMAZ.
    is_error_fallback = is_coach_error_fallback(final_text)

    # Geçmiş client'ta (widget sessionStorage) tutuluyor; client modunda session'a
    # YAZMA. Yalnızca client history göndermezse eski cookie geçmişini güncelle.
    # B16: sağlayıcı hata-yedeği metnini geçmişe YAZMA — aksi halde bir sonraki
    # turda bağlam olarak geri beslenip modeli kirletiyordu.
    if not use_client and not is_error_fallback:
        new_history = history + [
            {"role": "user", "content": question[:COACH_HISTORY_CHAR_CAP]},
            {"role": "assistant", "content": final_text[:COACH_HISTORY_CHAR_CAP]},
        ]
        session["coach_history"] = new_history[-COACH_HISTORY_LIMIT:]
    return final_text


def _run_coach_conversation_openai(user_id, question, context, history,
                                   language="tr", deadline=None):
    """OpenAI function-calling döngüsü: system → (gerekirse araç çağrıları) → final metin.
    Geçmişi session'a YAZMAZ (çağıran yönlendirici halleder)."""
    if deadline is None:
        deadline = _coach_turn_deadline()
    messages = prompt_builder.build_openai_messages(
        language, context, history, question,
        adaptive_plan_context=_adaptive_plan_context_enabled(),
        plan_mutation_tools=coach_plan_tools.plan_mutation_tools_enabled())

    final_text = ""
    for _ in range(_COACH_TOOL_LOOP_CAP):
        remaining = _remaining_coach_turn_seconds(deadline)
        if remaining <= 0:
            current_app.logger.warning("[COACH] OpenAI turn budget exhausted")
            return _coach_tool_fallback(language)
        try:
            with model_concurrency_slot("openai", deadline=deadline):
                remaining = _remaining_coach_turn_seconds(deadline)
                if remaining <= 0:
                    current_app.logger.warning(
                        "[COACH] OpenAI turn budget exhausted after model gate")
                    return _coach_tool_fallback(language)
                resp = openai_client.chat.completions.create(
                    model=OPENAI_MODEL,
                    messages=messages,
                    tools=_openai_tools_for_call(user_id),
                    tool_choice="auto",
                    max_tokens=700,
                    temperature=0.6,
                    timeout=min(30.0, remaining),
                )
        except Exception as e:
            if _remaining_coach_turn_seconds(deadline) <= 0:
                current_app.logger.warning(
                    "[COACH] OpenAI turn budget exhausted during model gate")
                return _coach_tool_fallback(language)
            current_app.logger.warning("[COACH] OpenAI çağrısı başarısız: %s", type(e).__name__)
            # Bu tur bir plan aracı koşturduysa "bir şeyler ters gitti" de aynı
            # yalandır: değişiklik commit'lidir. Aksi halde metin AYNEN eskisi.
            return _coach_tool_fallback(language, "error")
        if not resp.choices:
            # İçerik filtresi boş choices döndürebilir; ham IndexError yerine
            # boş final_text ile çık (çağıran yönlendirici dostça mesaja düşer).
            current_app.logger.warning("[COACH] OpenAI boş choices döndürdü")
            break
        msg = resp.choices[0].message
        tool_calls = msg.tool_calls or []

        if not tool_calls:
            final_text = coach_confirmation.grounded_provider_reply(
                user_id, language, msg.content or "")
            break

        # Araç isteyen assistant mesajını (tool_calls ile) sıraya ekle.
        messages.append({
            "role": "assistant",
            "content": msg.content or "",
            "tool_calls": [
                {"id": tc.id, "type": "function",
                 "function": {"name": tc.function.name, "arguments": tc.function.arguments}}
                for tc in tool_calls
            ],
        })
        # Her tool_call_id için tam olarak bir 'tool' yanıtı ekle (API zorunluluğu).
        payloads = []
        for tc in tool_calls:
            result = _dispatch_coach_tool(user_id, tc.function.name, tc.function.arguments)
            messages.append({"role": "tool", "tool_call_id": tc.id, "content": result})
            parsed = _tool_payload(result)
            if parsed is not None:
                payloads.append(parsed)
        owned = coach_confirmation.reply_after_tools(user_id, language, payloads)
        if owned:
            return owned
        # Döngü başa döner: model araç sonuçlarıyla final metni üretir ya da zincirler.
    else:
        final_text = _coach_tool_fallback(language)
    return final_text


def _adaptive_plan_context_enabled():
    """Koç promptunun planlama yetkisini AI_ADAPTIVE_PLAN_CONTEXT bayrağı belirler
    — bağlam metni DEĞİL. Bağlamda kullanıcı yazdığı alanlar (hafıza değerleri,
    arkadaş aktivitesi) var; kanonik başlığı taklit eden bir metin sistem promptunu
    çevirememeli. App context yoksa (birim testi) KAPALI kabul edilir."""
    return bool(has_app_context()
                and current_app.config.get("AI_ADAPTIVE_PLAN_CONTEXT", False))


def _build_bedrock_system(context, language="tr"):
    """Bedrock `system` parametresi (mantık: prompt_builder.build_bedrock_system).
    Modül-global BEDROCK_PROMPT_CACHE çağrı anında okunur — testler patch'ler."""
    return prompt_builder.build_bedrock_system(
        context, language, prompt_cache=BEDROCK_PROMPT_CACHE,
        adaptive_plan_context=_adaptive_plan_context_enabled(),
        plan_mutation_tools=coach_plan_tools.plan_mutation_tools_enabled())


def _anthropic_tools_for_call(user_id=None):
    """COACH_TOOLS_ANTHROPIC'in çağrı-zamanı kopyası (mantık:
    prompt_builder.anthropic_tools_for_call). Modül-global BEDROCK_PROMPT_CACHE
    çağrı anında okunur — testler bu globali monkeypatch'ler.

    PR3: plan araçları bayrak AÇIKken _coach_tool_defs_for_call() üzerinden
    eklenir; cache breakpoint yine SON araca konur, yani bayrak durumu değişmediği
    sürece sıra sabit ve önbellek stabildir."""
    tools = [_to_anthropic_tool(t) for t in _coach_tool_defs_for_call(user_id)]
    return prompt_builder.anthropic_tools_for_call(
        tools, prompt_cache=BEDROCK_PROMPT_CACHE)


def _tool_payload(raw):
    try:
        payload = json.loads(raw)
    except (TypeError, ValueError):
        return None
    return payload if isinstance(payload, dict) else None


def _first_text_block(resp):
    for block in getattr(resp, "content", None) or []:
        if getattr(block, "type", None) == "text":
            return block.text or ""
    return ""


def _run_coach_conversation_bedrock(user_id, question, context, history,
                                    language="tr", deadline=None):
    """Bedrock (Anthropic Messages API) araç-kullanım döngüsü. stop_reason=='tool_use'
    olduğu sürece araçları çalıştırır, tool_result'ları geri besler ve modelin final
    metnine (stop_reason=='end_turn') ulaşana dek zincirler (güvenli üst sınır).

    İlk create() çağrısı hiçbir araç çalışmadan hata verirse _BedrockFallback fırlatır
    (yönlendirici OpenAI'ya düşer). Bir araç YAN ETKİ ürettikten sonraki hatada
    sağlayıcı DEĞİŞTİRİLMEZ — yumuşak hata metni döner."""
    if deadline is None:
        deadline = _coach_turn_deadline()
    system = _build_bedrock_system(context, language)
    tools = _anthropic_tools_for_call(user_id)
    convo = prompt_builder.build_anthropic_messages(history, question)
    max_tokens = min(700, BEDROCK_MAX_TOKENS)

    tools_ran = 0
    for _ in range(_COACH_TOOL_LOOP_CAP):
        remaining = _remaining_coach_turn_seconds(deadline)
        if remaining <= 0:
            current_app.logger.warning("[COACH][Bedrock] turn budget exhausted")
            return _coach_tool_fallback(language)
        # B4: create() YANINDA yanıt ayrıştırma da korunmalı — `resp.content` None
        # (→ TypeError) gibi create sonrası hatalar önceden _BedrockFallback DIŞINDA
        # kaçıp yönlendiricinin OpenAI yedeğini atlayarak koçu 500'lüyordu. Aynı
        # tools_ran mantığını uygula: hiç araç çalışmadıysa OpenAI'ya düş, çalıştıysa
        # sağlayıcı değiştirme (yan etkiyi tekrarlama) → yumuşak hata.
        try:
            with model_concurrency_slot("bedrock", deadline=deadline):
                remaining = _remaining_coach_turn_seconds(deadline)
                if remaining <= 0:
                    current_app.logger.warning(
                        "[COACH][Bedrock] turn budget exhausted after model gate")
                    return _coach_tool_fallback(language)
                resp = bedrock_client.messages.create(
                    model=BEDROCK_MODEL,
                    max_tokens=max_tokens,
                    system=system,
                    messages=convo,
                    tools=tools,
                    timeout=min(BEDROCK_CALL_TIMEOUT_SECONDS, remaining),
                )

            if getattr(resp, "stop_reason", None) != "tool_use":
                text = _first_text_block(resp)
                if text:
                    return coach_confirmation.grounded_provider_reply(
                        user_id, language, text)
                # Metin bloğu yok: hiç araç çalışmadıysa OpenAI'ya düş (soru
                # cevaplanabilirdi); araç çalıştıysa sağlayıcı değiştirme.
                if tools_ran == 0:
                    raise _BedrockFallback("boş Bedrock yanıtı (metin bloğu yok)")
                # C3: hard-coded TR metin yerine dile göre yedek — EN kullanıcı
                # Türkçe hata görmesin.
                return _coach_tool_fallback(language)

            # Araç isteyen assistant turunu (tool_use bloklarıyla) olduğu gibi ekle.
            convo.append({"role": "assistant", "content": resp.content})
            tool_results = []
            payloads = []
            for block in resp.content:
                if getattr(block, "type", None) == "tool_use":
                    out = _dispatch_coach_tool(user_id, block.name, json.dumps(block.input or {}))
                    tool_results.append({"type": "tool_result", "tool_use_id": block.id, "content": out})
                    tools_ran += 1
                    parsed = _tool_payload(out)
                    if parsed is not None:
                        payloads.append(parsed)
            convo.append({"role": "user", "content": tool_results})
            owned = coach_confirmation.reply_after_tools(user_id, language, payloads)
            if owned:
                return owned
        except _BedrockFallback:
            raise
        except Exception as e:
            if _remaining_coach_turn_seconds(deadline) <= 0:
                current_app.logger.warning(
                    "[COACH][Bedrock] turn budget exhausted during provider call")
                return _coach_tool_fallback(language)
            if tools_ran == 0:
                raise _BedrockFallback(f"{type(e).__name__}: {e}")
            current_app.logger.warning("[COACH][Bedrock] araç sonrası çağrı/ayrıştırma hatası: %s", e)
            return _coach_tool_fallback(language)
        # Döngü başa döner: model araç sonuçlarıyla final metni üretir ya da zincirler.

    return _coach_tool_fallback(language)


def generate_coach_reply(name, age, gender, weight, height,
                         goal, level, current_activity,
                         bmr, tdee, target_calories,
                         training_plan, nutrition_plan,
                         user_message,
                         previous_weight=None, days_passed=None, language="tr"):
    """İstem şablonu app/prompts/goals.py'de (WS4); burada yalnızca sağlayıcı
    çağrısı + dostça hata yedeği kalır. training_plan/nutrition_plan imza
    uyumluluğu için korunur (istemde kullanılmaz — eski davranışla aynı)."""
    prompt, system_prompt = build_plan_reply_prompt(
        name, age, gender, weight, height, goal, level, current_activity,
        bmr, tdee, target_calories, user_message,
        previous_weight=previous_weight, days_passed=days_passed,
        language=language)
    try:
        return _heavy_chat(
            messages=[{"role": "user", "content": prompt}],
            system_prompt=system_prompt,
            max_tokens=700,
            temperature=0.7,
        )
    except Exception:
        current_app.logger.exception("Koç yorumu üretilemedi")
        return ("Coach feedback is unavailable right now, please try again."
                if _coach_lang(language) == "en"
                else "Koç yorumu şu an alınamıyor, lütfen tekrar dene.")


def generate_checkin_feedback(name, weight, prev_weight, days_passed,
                               goal, yogunluk, fatigue, overload,
                               uyku, beslenme, note, language="tr"):
    """İstem şablonu app/prompts/progress.py'de (WS4); burada yalnızca sağlayıcı
    çağrısı + dostça hata yedeği kalır."""
    prompt, system_prompt = build_checkin_feedback_prompt(
        name, weight, prev_weight, days_passed, goal, yogunluk, fatigue,
        overload, uyku, beslenme, note, language=language)
    try:
        return _heavy_chat(
            messages=[{"role": "user", "content": prompt}],
            system_prompt=system_prompt,
            max_tokens=400,
            temperature=0.7,
        )
    except Exception:
        current_app.logger.exception("Check-in geri bildirimi üretilemedi")
        return ("Feedback is unavailable right now, please try again."
                if _coach_lang(language) == "en"
                else "Geri bildirim şu an alınamadı, lütfen tekrar dene.")
